import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u08")

L(1, "Ter: o verbo hebben", "ik heb, jij hebt, hij heeft — e irmãos.",
  ["Conjugar «hebben» no presente", "Dizer quantos irmãos tem"],
  vocab=[V("v-hebben","hebben","ter","verb",note="ik heb, jij hebt, u hebt/heeft, hij/zij heeft, wij/jullie/zij hebben"),
         V("v-broer","broer","irmão","noun","de","broers"), V("v-zus","zus","irmã","noun","de","zussen"),
         V("v-kind","kind","criança|filho","noun","het","kinderen",note="Plural irregular: kinderen.")],
  ex=[("Ik heb een broer.","Tenho um irmão."),("Hij heeft twee zussen.","Ele tem duas irmãs."),("Heb jij kinderen?","Tens filhos?")],
  gram=[G("g-hebben","Hebben","**hebben** é irregular: ik **heb**, jij **hebt**, u **hebt** (ou heeft), hij/zij/het **heeft**, wij/jullie/zij **hebben**. Na pergunta com jij: **heb jij…?**",
    [("Wij hebben een hond.","Temos um cão."),("Heeft zij een fiets?","Ela tem uma bicicleta?")],
    "«Hebben» é «ter» para posse, família e também fome ou sede (ik heb honger = tenho fome), mas NÃO para a idade: diz-se «ik ben 30».")],
  review=["v-twee","v-drie","v-hond","v-fiets"],
  exs=[
    CJ("hebben","ik","Ik ___ een broer.", ["heb"], "ik heb.", ["v-hebben","v-broer"]),
    CJ("hebben","hij","Hij ___ twee zussen.", ["heeft"], "hij/zij heeft — forma irregular.", ["v-hebben","v-zus"]),
    CJ("hebben","wij","Wij ___ een hond.", ["hebben"], "Plural: hebben.", ["v-hebben"]),
    MA([("broer","irmão"),("zus","irmã"),("kind","criança"),("hebben","ter")], "Família e o verbo ter.", ["v-broer","v-zus","v-kind","v-hebben"]),
    MC("Qual é o plural de «kind»?", ["*kinderen","kinden|É irregular: kinderen.","kinds|Não existe."], "het kind → de kinderen.", ["v-kind"]),
    AR("kind","a criança","het", "«Het kind», mas «de kinderen».", ["v-kind"]),
    TR("pt-nl","Tens filhos?", ["Heb [jij|je] kinderen"], "Pergunta: heb jij…? (sem -t).", ["v-hebben","v-kind"], bank=["Heb","jij","kinderen?","Hebt","kinds"]),
    TR("nl-pt","Zij heeft een zus en een broer.", ["(Ela )tem uma irmã e um irmão"], "zij heeft = ela tem.", ["v-zus","v-broer"]),
    FE(["Hij","hebt","een","fiets."], 1, "heeft", "Com «hij»: heeft.", ["v-hebben"]),
    LI("Heb jij een broer?", ["Heb jij een broer"], "Tens um irmão?", "Pergunta com jij: heb (sem -t).", ["v-hebben","v-broer"]),
  ], diff=1, mins=5)

L(2, "Pais e filhos", "pai, mãe, pais, filho, filha.",
  ["Falar dos pais e dos filhos", "Distinguir «familie» e «gezin»"],
  vocab=[V("v-vader","vader","pai","noun","de","vaders"), V("v-moeder","moeder","mãe","noun","de","moeders"),
         V("v-ouders","ouders","pais","noun","de",note="Pai e mãe juntos (só plural)."), V("v-dochter","dochter","filha","noun","de","dochters"),
         V("v-familie","familie","família (alargada)","noun","de"), V("v-gezin","gezin","família (pais e filhos)","noun","het",note="O agregado: pais e filhos que vivem juntos.")],
  ex=[("Mijn ouders wonen in Porto.","Os meus pais vivem no Porto."),("Mijn moeder heet Maria.","A minha mãe chama-se Maria."),("Wij zijn een gezin van vier.","Somos uma família de quatro.")],
  gram=[G("g-gezin-familie","Gezin ou familie?","**het gezin** é a família nuclear (pais e filhos em casa). **de familie** é a família alargada (avós, tios, primos). *Ik heb een groot gezin* = tenho muitos filhos; *ik heb een grote familie* = tenho muitos parentes.",
    [("ons gezin","a nossa família (em casa)"),("mijn familie in Portugal","a minha família em Portugal")],
    "O português usa «família» para as duas coisas.")],
  review=["v-zoon","v-hebben","v-wonen","v-heten"],
  exs=[
    MA([("vader","pai"),("moeder","mãe"),("ouders","pais"),("dochter","filha")], "Família próxima.", ["v-vader","v-moeder","v-ouders","v-dochter"]),
    MC("«Mijn ouders» são…", ["*o meu pai e a minha mãe","os meus parentes|Isso seria «mijn familie».","os meus avós|Os avós são «grootouders»."], "ouders = pais.", ["v-ouders"]),
    AR("gezin","a família (nuclear)","het", "«Het gezin».", ["v-gezin"]),
    TR("pt-nl","A minha mãe chama-se Maria.", ["Mijn moeder heet Maria"], "heten: zij heet.", ["v-moeder","v-heten"], bank=["Mijn","moeder","heet","Maria","heten","vader"]),
    TR("nl-pt","Mijn ouders wonen in Porto.", ["Os meus pais [vivem|moram] no Porto"], "ouders é plural: wonen.", ["v-ouders","v-wonen"]),
    FB("Mijn ___ is twaalf en mijn zoon is negen.", ["dochter"], "dochter = filha.", ["v-dochter"], choices=["dochter","vader","ouders"], tr="A minha filha tem doze anos e o meu filho nove."),
    FE(["Mijn","ouders","woont","in","Lissabon."], 2, "wonen", "«ouders» é plural: wonen.", ["v-ouders"]),
    MC("Tem três filhos. Como diz «Tenho uma família grande»?", ["*Ik heb een groot gezin.","Ik heb een grote ouders.|«ouders» são só pai e mãe.","Ik ben een groot gezin.|Usa-se «hebben»."], "Para filhos em casa: gezin.", ["v-gezin"]),
    LI("Dit is mijn vader.", ["Dit is mijn vader"], "Este é o meu pai.", "«v» inicial quase como «f».", ["v-vader"]),
    WO("Os meus pais são simpáticos.", ["Mijn","ouders","zijn","aardig"], "Plural: zijn.", ["v-ouders","v-aardig"]),
  ], diff=1, mins=5)

L(3, "Meu, teu, dele, dela", "Os possessivos.",
  ["Usar os possessivos neerlandeses"],
  vocab=[V("v-jouw","jouw","teu|tua","determiner",note="Forma forte; átona: je."), V("v-uw","uw","seu|sua (formal)","determiner"),
         V("v-zijn-poss","zijn","seu|sua (dele)","determiner",note="Igual ao verbo «zijn», mas significa «dele»."),
         V("v-haar","haar","seu|sua (dela)","determiner",note="Também significa «cabelo» (het haar)."),
         V("v-ons","ons","nosso|nossa","determiner",note="ons com palavras het; onze com palavras de e no plural."),
         V("v-hun","hun","seu|sua (deles)","determiner")],
  ex=[("Zijn broer heet Tom.","O irmão dele chama-se Tom."),("Haar zus woont in Gent.","A irmã dela vive em Gent."),("ons huis, onze straat","a nossa casa, a nossa rua"),("Wat is uw naam?","Qual é o seu nome?")],
  gram=[G("g-possessivos","Possessivos","mijn (meu), **jouw/je** (teu), **uw** (seu, formal), **zijn** (dele), **haar** (dela), **ons/onze** (nosso), **jullie** (vosso), **hun** (deles). Não levam artigo. **ons** usa-se com palavras «het» no singular (*ons huis*); **onze** com palavras «de» e no plural (*onze straat, onze kinderen*).",
    [("zijn fiets","a bicicleta dele"),("haar fiets","a bicicleta dela")],
    "Em português «seu» é ambíguo (dele, dela, de você). O neerlandês distingue: zijn (dele), haar (dela), uw (de você/do senhor).")],
  review=["v-mijn","v-broer","v-zus","v-huis","v-straat","v-naam"],
  exs=[
    MA([("zijn","dele"),("haar","dela"),("hun","deles"),("uw","seu (formal)")], "Possessivos da 3.ª pessoa e formal.", ["v-zijn-poss","v-haar","v-hun","v-uw"]),
    MC("Como se diz «a irmã dele»?", ["*zijn zus","haar zus|«haar» = dela.","hun zus|«hun» = deles."], "dele = zijn.", ["v-zijn-poss"]),
    MC("«ons» ou «onze»: ___ huis", ["*ons","onze|«huis» é uma palavra het: ons huis."], "het huis → ons huis.", ["v-ons"]),
    MC("«ons» ou «onze»: ___ kinderen", ["*onze","ons|No plural usa-se sempre «onze»."], "Plural → onze.", ["v-ons"]),
    TR("pt-nl","Qual é o seu nome? (formal)", ["Wat is uw naam"], "Formal: uw.", ["v-uw","v-naam"]),
    TR("nl-pt","Haar broer woont in Gent.", ["O irmão dela [vive|mora] em Gent"], "haar = dela.", ["v-haar","v-broer"]),
    FB("Tom en Eva hebben een hond. ___ hond heet Max.", ["Hun"], "De Tom e Eva = deles: hun.", ["v-hun"], choices=["Hun","Zijn","Haar"], tr="O Tom e a Eva têm um cão. O cão deles chama-se Max."),
    FE(["Dit","is","de","mijn","fiets."], 2, "(retirar)", "Os possessivos não levam artigo: dit is mijn fiets.", ["v-mijn"]),
    LI("Is dit jouw boek?", ["Is dit jouw boek"], "Este livro é teu?", "«jouw» com ênfase (teu, não meu).", ["v-jouw","v-boek"]),
    WO("A nossa rua é bonita.", ["Onze","straat","is","mooi"], "de straat → onze straat.", ["v-ons","v-straat"]),
  ], diff=2, mins=6)

L(4, "Avós, tios e primos", "A família alargada e o estado civil.",
  ["Falar da família alargada", "Dizer se é casado"],
  vocab=[V("v-opa","opa","avô","noun","de","opa's"), V("v-oma","oma","avó","noun","de","oma's"),
         V("v-oom","oom","tio","noun","de","ooms"), V("v-tante","tante","tia","noun","de","tantes"),
         V("v-neef","neef","primo|sobrinho","noun","de","neven"), V("v-nicht","nicht","prima|sobrinha","noun","de","nichten"),
         V("v-getrouwd","getrouwd","casado","adjective")],
  ex=[("Mijn oma is tachtig.","A minha avó tem oitenta anos."),("Ik ben getrouwd.","Sou casado/a."),("Mijn man heet Rui.","O meu marido chama-se Rui."),("Mijn neef woont in Brazilië.","O meu primo vive no Brasil.")],
  gram=[G("g-neef-nicht","Neef e nicht","**neef** pode ser «primo» ou «sobrinho»; **nicht** pode ser «prima» ou «sobrinha». O contexto decide. Também: **mijn man** = o meu marido; **mijn vrouw** = a minha mulher.",
    [("de zoon van mijn broer = mijn neef","o filho do meu irmão = o meu sobrinho")],
    "Em português temos palavras diferentes para primo e sobrinho; em neerlandês é a mesma.")],
  review=["v-man","v-vrouw","v-familie","v-hebben"],
  exs=[
    MA([("opa","avô"),("oma","avó"),("oom","tio"),("tante","tia")], "Família alargada.", ["v-opa","v-oma","v-oom","v-tante"]),
    MC("O filho da minha irmã é o meu…", ["*neef","oom|«oom» = tio.","opa|«opa» = avô."], "neef = sobrinho (ou primo).", ["v-neef"]),
    TR("nl-pt","Ik ben getrouwd.", ["Sou casad[o|a]","Estou casad[o|a]"], "getrouwd = casado.", ["v-getrouwd"]),
    TR("pt-nl","O meu marido chama-se Rui.", ["Mijn man heet Rui"], "mijn man = o meu marido.", ["v-man"], bank=["Mijn","man","heet","Rui","vrouw","heten"]),
    TR("pt-nl","A minha avó tem oitenta anos.", ["Mijn oma is tachtig( jaar)"], "Idade com «zijn».", ["v-oma","v-tachtig"]),
    FB("De zus van mijn moeder is mijn ___.", ["tante"], "A irmã da mãe = tia.", ["v-tante"], choices=["tante","nicht","oma"], tr="A irmã da minha mãe é a minha tia."),
    LI("Mijn neef woont in Brazilië.", ["Mijn neef woont in Brazilië"], "O meu primo vive no Brasil.", "«neef» com «ee» longo.", ["v-neef","v-brazilie"]),
    FE(["Mijn","opa","heeft","negentig","jaar."], 2, "is", "Idade: mijn opa is negentig jaar.", ["v-opa"]),
    DL([("Sanne","Ben je getrouwd?","És casado?"),("Pedro","")], ["*Ja, mijn vrouw heet Joana.","Ja, mijn man heet Joana.|«man» é marido.","Ja, ik heb getrouwd.|Usa-se «zijn»: ik ben getrouwd."], "ik ben getrouwd; mijn vrouw = a minha mulher.", ["v-getrouwd","v-vrouw"]),
    CO("text","A família do Tom", "Tom is getrouwd met Lisa. Ze hebben twee kinderen: een zoon en een dochter. De ouders van Lisa wonen in Groningen. Tom heeft ook een oom in Canada.",
       [("Com quem é casado o Tom?", ["*Com a Lisa","Com a filha","Não é casado"]),("Onde vivem os pais da Lisa?", ["*Em Groningen","No Canadá","Com o Tom"])],
       "«getrouwd met» = casado com.", ["v-getrouwd","v-ouders","v-oom"]),
  ], diff=2, mins=6)

L(5, "A minha família", "Revisão: falar da família com hebben, zijn e possessivos.",
  ["Descrever a própria família em poucas frases"],
  ex=[("Ik heb een klein gezin: mijn vrouw, mijn dochter en ik.","Tenho uma família pequena: a minha mulher, a minha filha e eu.")],
  review=["v-hebben","v-gezin","v-ouders","v-broer","v-zus","v-zijn-poss","v-haar","v-ons","v-kind"],
  exs=[
    CJ("hebben","zij (ela)","Zij ___ drie kinderen.", ["heeft"], "zij heeft.", ["v-hebben","v-kind"]),
    CJ("hebben","jullie","___ jullie een hond?", ["Hebben"], "jullie hebben.", ["v-hebben"]),
    MC("O pai do meu pai é o meu…", ["*opa","oom|O irmão do pai é o tio (oom).","neef|neef = primo ou sobrinho."], "opa = avô.", ["v-opa"]),
    MA([("mijn broer","o meu irmão"),("zijn zus","a irmã dele"),("haar vader","o pai dela"),("onze kinderen","os nossos filhos")], "Possessivos com família.", ["v-broer","v-zijn-poss","v-haar","v-ons"]),
    TR("pt-nl","Tenho dois irmãos e uma irmã.", ["Ik heb twee broers en een zus"], "Plural: broers.", ["v-broer","v-zus"]),
    TR("nl-pt","Hun kinderen zijn heel aardig.", ["Os filhos deles são muito simpáticos","As crianças deles são muito simpáticas"], "hun = deles.", ["v-hun","v-kind"]),
    FE(["Wij","heeft","een","groot","gezin."], 1, "hebben", "wij hebben.", ["v-hebben"]),
    LI("Mijn ouders zijn getrouwd.", ["Mijn ouders zijn getrouwd"], "Os meus pais são casados.", "ouders → zijn.", ["v-ouders","v-getrouwd"]),
    CO("text","A família da Ana", "Ik heet Ana en ik ben vierendertig. Ik woon met mijn man en onze zoon in Leiden. Mijn ouders en mijn broer wonen in Portugal. Mijn broer heeft twee dochters: mijn nichtjes!",
       [("Com quem vive a Ana?", ["*Com o marido e o filho","Com os pais","Com o irmão"]),("Quantas filhas tem o irmão?", ["*Duas","Uma","Nenhuma"])],
       "«nichtjes» = sobrinhas (forma carinhosa de «nicht»).", ["v-ouders","v-broer","v-nicht"]),
    SW("Descreva a sua família em 2–3 frases (hebben, possessivos).", ["Ik heb een [broer|zus](.) Mijn ouders wonen in [Portugal|Lissabon|Porto]","Ik ben getrouwd(.) Mijn [man|vrouw] heet [Rui|Joana]"],
       ["Usa «hebben» corretamente (ik heb, hij heeft)","Usa possessivos (mijn, zijn, haar…)","Idade com «zijn», se a disser"], 6, "Modelo: «Ik heb een broer en een zus. Mijn ouders wonen in Porto.»", ["v-hebben"]),
  ], diff=2, mins=7)

W()
